<template><div class="joint-row" :data-joint-id="joint.id"><span class="joint-name" :title="joint.name">{{joint.name}}</span><el-slider class="joint-slider" :model-value="sliderValue" :min="sliderMin" :max="sliderMax" :step="sliderStep" :disabled="disabled" @input="preview" @change="commit"/><JointValueInput :joint="joint" :value="value" :unit="unit" :precision="precision" :disabled="disabled" @preview="previewInput" @commit="commitInput"/><span class="joint-unit">{{disabledLabel||unit}}</span></div></template>
<script setup lang="ts">
import {computed} from 'vue';import type {JointNode} from '@/types/scene';import JointValueInput,{type RotationUnit,type TranslationUnit} from './JointValueInput.vue'
const props=defineProps<{joint:JointNode;value:number;rotationUnit?:RotationUnit;translationUnit?:TranslationUnit;precision?:number}>();const emit=defineEmits<{preview:[id:string,value:number];commit:[id:string,value:number]}>();
const disabled=computed(()=>['fixed','planar','floating'].includes(props.joint.type));const disabledLabel=computed(()=>props.joint.type==='fixed'?'Fixed':['planar','floating'].includes(props.joint.type)?'Unsupported':'');const unit=computed(()=>props.joint.type==='prismatic'?(props.translationUnit??'m'):(props.rotationUnit??'rad'));const precision=computed(()=>props.precision??3);const sliderMin=computed(()=>props.joint.limit.lower??(props.joint.type==='prismatic'?-1:-Math.PI));const sliderMax=computed(()=>props.joint.limit.upper??(props.joint.type==='prismatic'?1:Math.PI));const sliderStep=computed(()=>props.joint.type==='prismatic'?.001:.01);const sliderValue=computed(()=>Math.min(sliderMax.value,Math.max(sliderMin.value,props.value)))
function number(value:number|number[]){return Number(value)}function preview(value:number|number[]){emit('preview',props.joint.id,number(value))}function commit(value:number|number[]){emit('commit',props.joint.id,number(value))}function previewInput(value:number){emit('preview',props.joint.id,value)}function commitInput(value:number){emit('commit',props.joint.id,value)}
</script>
<style scoped>.joint-row{display:grid;grid-template-columns:minmax(150px,230px) minmax(180px,1fr) 110px 70px;align-items:center;gap:12px;min-width:650px}.joint-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.joint-unit{color:#7894a8}.joint-slider{min-width:0}</style>
